import base64,datetime,hashlib,importlib.metadata,json,os,pwd,subprocess,sys
from pathlib import Path
root=Path('/data/robot/p001');e=root/'e163'
def checked(p):
 p=Path(p)
 assert p.is_absolute() and p.is_relative_to(root) and p.resolve()==p
 assert not any(q.is_symlink() for q in (p,*p.parents))
 return p
assert pwd.getpwuid(os.geteuid()).pw_name=='robot'
assert checked(e).is_dir()
assert not checked(e/'o002').exists() and not checked(e/'run002').exists()
assert not checked(e/'repair002.zip').exists()
raw=base64.b64decode('')
assert hashlib.sha256(raw).hexdigest()=='d5764b8091aba95b7223ee7cdcb18d752e123d17063bb0c936775753f6e8189d'
spec=json.loads(raw)
def verify(p,r):
 b=checked(p).read_bytes()
 assert len(b)==r['bytes'] and hashlib.sha256(b).hexdigest()==r['sha256'],str(p)
for r in spec['source_files']:verify(e/'s001'/r['path'],r)
for r in spec['input_files']:verify(r['remote_path'],r)
verify(spec['foundation']['remote_path'],spec['foundation'])
versions={}
for line in checked(e/'s001/requirements-lock.txt').read_text().splitlines():
 if line and not line.startswith('#'):
  name,v=line.split('==');versions[name]=importlib.metadata.version(name)
  assert versions[name]==v,name
def usage(p):return int(subprocess.check_output(['du','-sb','-x','--',str(p)],text=True,timeout=45).split()[0])
pbytes,ebytes=usage(root),usage(e);v=os.statvfs(e)
assert pbytes-ebytes==spec['project_bytes_before']
reserve=110000000
assert pbytes+reserve<100000000000 and ebytes+reserve<268435456
assert v.f_bavail*v.f_frsize>reserve and v.f_favail>1000
r={'status':'RUN002_TRANSFER_ADMISSION_PASS','measured_utc':datetime.datetime.now(datetime.timezone.utc).isoformat(),'project_bytes':pbytes,'e163_bytes':ebytes,'project_non_e163_bytes':pbytes-ebytes,'available_bytes':v.f_bavail*v.f_frsize,'available_inodes':v.f_favail,'source_files_verified':21,'input_foundation_files_verified':49,'dependencies':versions,'python':sys.version,'campaign_started':False,'old_run001_preserved':True}
b=base64.b64encode(json.dumps(r).encode()).decode()
print('RUN002_ADMISSION_B64_BEGIN')
for i in range(0,len(b),60):print(b[i:i+60])
print('RUN002_ADMISSION_B64_END')
